#botaook2.elementor-button {
  background: linear-gradient(135deg, #C4857E 0%, #DDB4A9 100%) !important;
  color: #FFFFFF;
  border: 0;
  border-radius: 8px;
  padding: 16px 40px;
  font-weight: 400;
  font-size: 17x;
  cursor: pointer;
  animation: pulseButtonRosa 2s infinite;
  transition: transform .3s ease;
}

#meuBotaoPersonalizado.elementor-button:hover {
  transform: scale(1.08);
}

@keyframes pulseButtonRosa {
    0% { box-shadow: 0 0 0 0 rgba(196, 133, 126, 1); }
    50% { box-shadow: 0 0 0 20px rgba(196, 133, 126, 0); }
    100% { box-shadow: 0 0 0 50px rgba(196, 133, 126, 0); }
}

